use std::io
use std::collections::HashMap

fn main() {
    let text = io::read_to_string() ?? ""
    let mut k = 0
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut cur = ""
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            k = line.trim().parse::<int>() ?? 0
            continue
        }
        let mut s = line.to_string()
        s.push_str(" ")
        for c in s.chars() {
            if c.is_ascii_alphanumeric() {
                cur.push_str(c.to_lowercase().to_string())
            } else if cur.len() > 0 {
                *counts.entry(cur).or_insert(0) += 1
                cur = ""
            }
        }
    }
    let mut items: Vec<(string, int)> = Vec::new()
    for (w, n) in counts {
        items.push((w, n))
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(&a.1)
        } else {
            a.0.cmp(&b.0)
        }
    })
    let mut i = 0
    for item in items {
        if i >= k {
            break
        }
        println("${item.0} ${item.1}")
        i += 1
    }
}

